void UTIL_Log_Write(UTIL_Log_Level_e level, const char* tag, const char* fmt, ...)
{
  UNITY_LINE_TYPE cmock_line = TEST_LINE_NUM;
  CMOCK_UTIL_Log_Write_CALL_INSTANCE* cmock_call_instance;
  UNITY_SET_DETAIL(CMockString_UTIL_Log_Write);
  cmock_call_instance = (CMOCK_UTIL_Log_Write_CALL_INSTANCE*)CMock_Guts_GetAddressFor(Mock.UTIL_Log_Write_CallInstance);
  Mock.UTIL_Log_Write_CallInstance = CMock_Guts_MemNext(Mock.UTIL_Log_Write_CallInstance);
  if (Mock.UTIL_Log_Write_IgnoreBool)
  {
    UNITY_CLR_DETAILS();
    return;
  }
  if (!Mock.UTIL_Log_Write_CallbackBool &&
      Mock.UTIL_Log_Write_CallbackFunctionPointer != NULL)
  {
    Mock.UTIL_Log_Write_CallbackFunctionPointer(level, tag, fmt, Mock.UTIL_Log_Write_CallbackCalls++);
    UNITY_CLR_DETAILS();
    return;
  }
  UNITY_TEST_ASSERT_NOT_NULL(cmock_call_instance, cmock_line, CMockStringCalledMore);
  cmock_line = cmock_call_instance->LineNumber;
  if (cmock_call_instance->CallOrder > ++GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledEarly);
  if (cmock_call_instance->CallOrder < GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledLate);
  if (!cmock_call_instance->ExpectAnyArgsBool)
  {
  if (!cmock_call_instance->IgnoreArg_level)
  {
    UNITY_SET_DETAILS(CMockString_UTIL_Log_Write,CMockString_level);
    UNITY_TEST_ASSERT_EQUAL_MEMORY(&cmock_call_instance->Expected_level, &level, sizeof(UTIL_Log_Level_e), cmock_line, CMockStringMismatch);
  }
  if (!cmock_call_instance->IgnoreArg_tag)
  {
    UNITY_SET_DETAILS(CMockString_UTIL_Log_Write,CMockString_tag);
    UNITY_TEST_ASSERT_EQUAL_STRING(cmock_call_instance->Expected_tag, tag, cmock_line, CMockStringMismatch);
  }
  if (!cmock_call_instance->IgnoreArg_fmt)
  {
    UNITY_SET_DETAILS(CMockString_UTIL_Log_Write,CMockString_fmt);
    UNITY_TEST_ASSERT_EQUAL_STRING(cmock_call_instance->Expected_fmt, fmt, cmock_line, CMockStringMismatch);
  }
  }
  if (Mock.UTIL_Log_Write_CallbackFunctionPointer != NULL)
  {
    UNITY_SET_DETAIL(CMockString_UTIL_Log_Write);
    Mock.UTIL_Log_Write_CallbackFunctionPointer(level, tag, fmt, Mock.UTIL_Log_Write_CallbackCalls++);
  }
  UNITY_CLR_DETAILS();
}

